// The layout kit's measured catch rate: every defect and false-failure page found in independent review rounds 5 to 8, with its
// classification. Run with `run.mjs --catch-rate` (Chromium). A case is caught when its own assertion (the one the
// contract maps to the defect's invariant) reports a violation other than a missing page element ("no fault on the
// page"). The run fails when a violation is missed and not disclosed in R41-11, or when a conforming page fails.
// verdict: 'violation' | 'conforming' | 'not a violation: <reason>' | 'not judged: <reason>'; disclosed: the R41-11 entry
// naming a known miss.
// body: the page body, or a function of P (a Forma pattern's HTML by name).

const remedy = '<style>a[href]{display:inline-flex;align-items:center;min-block-size:var(--ef-layout-target-min);min-inline-size:var(--ef-layout-target-min)}</style>';

// Round 8's full investigation screen in Save failed (navigation shell, record header, freshness, operation status,
// timeline, with the link remedy), run through every assertion that applies to a screen.
const screen = (state, lozState, opHtml) => P => remedy + `<div class="ef-site"><a class="ef-skip-link" href="#main">Skip to main content</a>` +
  P('navigation-shell').replace('<main class="ef-navigation-shell__content" id="overview"><h1>Overview</h1></main>',
   `<main class="ef-navigation-shell__content" id="main" tabindex="-1">
<header class="ef-record-header"><div class="ef-record-header__main"><nav aria-label="Breadcrumb"><a href="#ws">Workspace</a> <span aria-hidden="true">/</span> <a href="#inv">Investigations</a></nav><div class="ef-record-header__title"><div><span class="ef-record-header__type">Investigation</span><h1>Checkout latency regression</h1></div><span class="ef-status-lozenge" data-state="${lozState}">${state}</span></div><p>Opened by the platform team</p></div></header>
<p class="ef-freshness"><span class="ef-freshness__label">Last saved</span> <time datetime="2026-10-30T04:30:00Z">04:30 UTC</time></p>
${opHtml}
${P('timeline')}
</main>`) + '</div>';
const saveFailedOp = `<section class="ef-operation-status" aria-labelledby="op"><div class="ef-operation-status__symbol" aria-hidden="true">!</div><div><h3 id="op">Save failed</h3><p>GitHub refused the save because the credential was refused. Your changes are kept in this tab.</p></div><div class="ef-operation-status__actions"><button type="button">Reconnect</button></div></section>`;

